-- W17 durable Outbox owner contract core (per PHASE-W16-OUTBOX-OWNER-CONTRACT-REVIEW-20261106 推荐 owner 合约):
-- Identity/Auth owner appends revocation facts to its own Outbox in the revocation transaction;
-- the Collaboration owner applies them through its own idempotent Inbox + cursor checkpoint.
-- One physical SQL statement per line for the repository migration runner.
DO $w17_outbox_roles$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='star_collaboration_owner') THEN CREATE ROLE star_collaboration_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT; ELSE ALTER ROLE star_collaboration_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT; END IF; IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='star_collaboration_runtime') THEN CREATE ROLE star_collaboration_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT; ELSE ALTER ROLE star_collaboration_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT; END IF; END $w17_outbox_roles$;
GRANT USAGE ON SCHEMA public TO star_collaboration_owner, star_collaboration_runtime;
-- Identity Outbox: append-only, owner-scoped; PK(stream_id, source_sequence) keeps the owner-monotonic replay order; UNIQUE(event_id) pins the stable event identity.
CREATE TABLE IF NOT EXISTS identity_device_outbox (stream_id UUID NOT NULL CHECK (stream_id <> '00000000-0000-0000-0000-000000000000'), source_sequence BIGINT NOT NULL CHECK (source_sequence > 0), event_id UUID NOT NULL CHECK (event_id <> '00000000-0000-0000-0000-000000000000'), event_type TEXT NOT NULL CHECK (event_type IN ('device.revoked')), schema_version INTEGER NOT NULL CHECK (schema_version = 1), tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), actor_id UUID NOT NULL CHECK (actor_id <> '00000000-0000-0000-0000-000000000000'), device_id UUID NOT NULL CHECK (device_id <> '00000000-0000-0000-0000-000000000000'), device_generation BIGINT NOT NULL CHECK (device_generation > 0), producer_id TEXT NOT NULL CHECK (producer_id = 'identity.device-revoke.v1'), occurred_at TIMESTAMPTZ NOT NULL, correlation_id UUID NOT NULL CHECK (correlation_id <> '00000000-0000-0000-0000-000000000000'), created_at TIMESTAMPTZ NOT NULL DEFAULT transaction_timestamp(), PRIMARY KEY (stream_id, source_sequence), UNIQUE (event_id));
CREATE INDEX IF NOT EXISTS idx_identity_device_outbox_created ON identity_device_outbox(created_at, stream_id, source_sequence);
ALTER TABLE identity_device_outbox ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_device_outbox FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS identity_outbox_owner_scope ON identity_device_outbox;
CREATE POLICY identity_outbox_owner_scope ON identity_device_outbox USING (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID AND actor_id=NULLIF(current_setting('app.actor_id',true),'')::UUID) WITH CHECK (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID AND actor_id=NULLIF(current_setting('app.actor_id',true),'')::UUID);
REVOKE ALL ON TABLE identity_device_outbox FROM PUBLIC;
REVOKE ALL ON TABLE identity_device_outbox FROM star_oauth_credential_owner;
GRANT SELECT, INSERT ON TABLE identity_device_outbox TO star_oauth_credential_owner;
CREATE OR REPLACE FUNCTION public.w17_notify_identity_outbox_wake() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog AS $function$ BEGIN PERFORM pg_catalog.pg_notify('star_identity_outbox_wake','changed'); RETURN NEW; END; $function$;
REVOKE ALL ON FUNCTION public.w17_notify_identity_outbox_wake() FROM PUBLIC;
DROP TRIGGER IF EXISTS w17_identity_outbox_wake ON identity_device_outbox;
CREATE TRIGGER w17_identity_outbox_wake AFTER INSERT ON identity_device_outbox FOR EACH ROW EXECUTE FUNCTION public.w17_notify_identity_outbox_wake();
-- Collaboration Inbox: idempotency unique constraint = producer + stream + sequence + event_id (review 合约 #4); WORM; digest pins the received wire identity for conflict isolation.
CREATE TABLE IF NOT EXISTS collaboration_device_inbox (tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), consumer_id TEXT NOT NULL DEFAULT 'collab.device-auth.v1' CHECK (consumer_id = 'collab.device-auth.v1'), producer_id TEXT NOT NULL CHECK (producer_id = 'identity.device-revoke.v1'), stream_id UUID NOT NULL CHECK (stream_id <> '00000000-0000-0000-0000-000000000000'), source_sequence BIGINT NOT NULL CHECK (source_sequence > 0), event_id UUID NOT NULL CHECK (event_id <> '00000000-0000-0000-0000-000000000000'), event_type TEXT NOT NULL CHECK (event_type IN ('device.revoked')), schema_version INTEGER NOT NULL CHECK (schema_version = 1), actor_id UUID NOT NULL CHECK (actor_id <> '00000000-0000-0000-0000-000000000000'), device_id UUID NOT NULL CHECK (device_id <> '00000000-0000-0000-0000-000000000000'), device_generation BIGINT NOT NULL CHECK (device_generation > 0), occurred_at TIMESTAMPTZ NOT NULL, correlation_id UUID NOT NULL CHECK (correlation_id <> '00000000-0000-0000-0000-000000000000'), event_digest BYTEA NOT NULL CHECK (octet_length(event_digest) = 32), receipt_id UUID NOT NULL DEFAULT gen_random_uuid(), committed_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(), transport_provider_id TEXT NOT NULL CHECK (transport_provider_id ~ '^[a-z0-9][a-z0-9-]{0,63}$'), transport_profile_id UUID NOT NULL CHECK (transport_profile_id <> '00000000-0000-0000-0000-000000000000'), PRIMARY KEY (tenant_id, consumer_id, producer_id, stream_id, source_sequence, event_id), UNIQUE (receipt_id));
-- Collaboration local invalidation projection: accelerates shared-work authorization expiry only; it is NOT the authoritative revocation fact (review 合约 #2/#6).
CREATE TABLE IF NOT EXISTS collaboration_device_projection (tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), consumer_id TEXT NOT NULL DEFAULT 'collab.device-auth.v1' CHECK (consumer_id = 'collab.device-auth.v1'), actor_id UUID NOT NULL CHECK (actor_id <> '00000000-0000-0000-0000-000000000000'), device_id UUID NOT NULL CHECK (device_id <> '00000000-0000-0000-0000-000000000000'), device_generation BIGINT NOT NULL CHECK (device_generation > 0), status TEXT NOT NULL CHECK (status = 'revoked'), source_event_id UUID NOT NULL CHECK (source_event_id <> '00000000-0000-0000-0000-000000000000'), invalidated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (tenant_id, consumer_id, actor_id, device_id));
-- Consumer checkpoint: opaque cursor handle bound to transport provider + profile (review 合约 #5); the profile participates in the primary key so cursors are never compared across providers.
CREATE TABLE IF NOT EXISTS collaboration_inbox_checkpoint (tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), consumer_id TEXT NOT NULL DEFAULT 'collab.device-auth.v1' CHECK (consumer_id = 'collab.device-auth.v1'), producer_id TEXT NOT NULL CHECK (producer_id = 'identity.device-revoke.v1'), stream_id UUID NOT NULL CHECK (stream_id <> '00000000-0000-0000-0000-000000000000'), transport_provider_id TEXT NOT NULL CHECK (transport_provider_id ~ '^[a-z0-9][a-z0-9-]{0,63}$'), transport_profile_id UUID NOT NULL CHECK (transport_profile_id <> '00000000-0000-0000-0000-000000000000'), cursor_handle BYTEA NOT NULL CHECK (octet_length(cursor_handle) <= 128), next_expected_sequence BIGINT NOT NULL DEFAULT 1 CHECK (next_expected_sequence > 0), suspended_reason TEXT CHECK (suspended_reason IN ('sequence_gap','stale_cursor','retention_gap')), suspended_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (tenant_id, consumer_id, producer_id, stream_id, transport_profile_id));
-- Integrity incidents: append-only receipts of digest conflicts, sequence gaps, stale cursors and rejected envelopes; bounded metadata only, never event payloads.
CREATE TABLE IF NOT EXISTS collaboration_device_event_incident (tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), incident_id UUID NOT NULL DEFAULT gen_random_uuid(), consumer_id TEXT NOT NULL DEFAULT 'collab.device-auth.v1' CHECK (consumer_id = 'collab.device-auth.v1'), producer_id TEXT NOT NULL CHECK (producer_id = 'identity.device-revoke.v1'), stream_id UUID NOT NULL CHECK (stream_id <> '00000000-0000-0000-0000-000000000000'), source_sequence BIGINT NOT NULL CHECK (source_sequence > 0), event_id UUID NOT NULL CHECK (event_id <> '00000000-0000-0000-0000-000000000000'), reason_code TEXT NOT NULL CHECK (reason_code IN ('digest_conflict','sequence_gap','stale_cursor','unknown_schema_version')), received_event_digest BYTEA CHECK (received_event_digest IS NULL OR octet_length(received_event_digest) = 32), stored_event_digest BYTEA CHECK (stored_event_digest IS NULL OR octet_length(stored_event_digest) = 32), observed_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (tenant_id, incident_id), UNIQUE (tenant_id, consumer_id, producer_id, stream_id, source_sequence, event_id, reason_code, received_event_digest));
ALTER TABLE collaboration_device_inbox ENABLE ROW LEVEL SECURITY;
ALTER TABLE collaboration_device_inbox FORCE ROW LEVEL SECURITY;
ALTER TABLE collaboration_device_projection ENABLE ROW LEVEL SECURITY;
