CREATE POLICY collaboration_owner_tenant_scope ON collaboration_device_inbox FOR ALL TO star_collaboration_owner USING (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID) WITH CHECK (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID);
DROP POLICY IF EXISTS collaboration_owner_tenant_scope ON collaboration_device_projection;
CREATE POLICY collaboration_owner_tenant_scope ON collaboration_device_projection FOR ALL TO star_collaboration_owner USING (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID) WITH CHECK (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID);
DROP POLICY IF EXISTS collaboration_owner_tenant_scope ON collaboration_inbox_checkpoint;
CREATE POLICY collaboration_owner_tenant_scope ON collaboration_inbox_checkpoint FOR ALL TO star_collaboration_owner USING (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID) WITH CHECK (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID);
DROP POLICY IF EXISTS collaboration_owner_tenant_scope ON collaboration_device_event_incident;
CREATE POLICY collaboration_owner_tenant_scope ON collaboration_device_event_incident FOR ALL TO star_collaboration_owner USING (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID) WITH CHECK (tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::UUID);
REVOKE ALL ON TABLE collaboration_device_inbox, collaboration_device_projection, collaboration_inbox_checkpoint, collaboration_device_event_incident FROM PUBLIC;
REVOKE ALL ON TABLE collaboration_device_inbox, collaboration_device_projection, collaboration_inbox_checkpoint, collaboration_device_event_incident FROM star_collaboration_runtime;
CREATE OR REPLACE FUNCTION public.w17_reject_collaboration_mutation() RETURNS TRIGGER AS $$ BEGIN RAISE EXCEPTION 'Collaboration device inbox and incidents are append-only'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS w17_collaboration_inbox_worm ON collaboration_device_inbox;
CREATE TRIGGER w17_collaboration_inbox_worm BEFORE UPDATE OR DELETE OR TRUNCATE ON collaboration_device_inbox FOR EACH STATEMENT EXECUTE FUNCTION public.w17_reject_collaboration_mutation();
