CREATE OR REPLACE FUNCTION public.w17_notify_collab_device_invalidated() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog AS $function$ BEGIN PERFORM pg_catalog.pg_notify('star_collab_device_invalidated',NEW.device_id::TEXT); RETURN NEW; END; $function$;
REVOKE ALL ON FUNCTION public.w17_notify_collab_device_invalidated() FROM PUBLIC;
DROP TRIGGER IF EXISTS w17_collaboration_projection_wake ON collaboration_device_projection;
CREATE TRIGGER w17_collaboration_projection_wake AFTER INSERT OR UPDATE OF device_generation,status ON collaboration_device_projection FOR EACH ROW EXECUTE FUNCTION public.w17_notify_collab_device_invalidated();
DO $w17_no_table_ownership$ BEGIN IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relowner='star_oauth_credential_owner'::regrole AND n.nspname='public' AND c.relname IN ('identity_device_outbox')) THEN RAISE EXCEPTION 'star_oauth_credential_owner must not own identity_device_outbox'; END IF; IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relowner='star_collaboration_owner'::regrole AND n.nspname='public' AND c.relname IN ('collaboration_device_inbox','collaboration_device_projection','collaboration_inbox_checkpoint','collaboration_device_event_incident')) THEN RAISE EXCEPTION 'star_collaboration_owner must not own Collaboration device tables'; END IF; END $w17_no_table_ownership$;
COMMENT ON TABLE identity_device_outbox IS 'T: append-only Identity-owner device revocation Outbox; metadata-only envelope (no token, proof, body or DEK), written in the same transaction as the revocation fact itself.';
COMMENT ON TABLE collaboration_device_inbox IS 'T: Collaboration-owner durable receipt; idempotency unique constraint is producer + stream + sequence + event_id; committed only together with the local invalidation projection and the cursor advance.';
COMMENT ON TABLE collaboration_device_projection IS 'T: Collaboration-local invalidation projection that only accelerates shared-work authorization expiry; the Identity owner binding remains the authoritative revocation fact.';
COMMENT ON TABLE collaboration_inbox_checkpoint IS 'T: consumer checkpoint; cursor_handle is opaque and bound to transport provider + profile; next_expected_sequence advances only inside the committed apply transaction.';
COMMENT ON TABLE collaboration_device_event_incident IS 'T: append-only receipts of digest conflicts, sequence gaps, stale cursors and rejected envelopes; bounded metadata, never event payloads.';
CREATE OR REPLACE FUNCTION public.commit_device_revoke_event_v1(p_tenant_id UUID,p_producer_id TEXT,p_stream_id UUID,p_source_sequence BIGINT,p_event_id UUID,p_event_type TEXT,p_schema_version INTEGER,p_actor_id UUID,p_device_id UUID,p_device_generation BIGINT,p_occurred_at TIMESTAMPTZ,p_correlation_id UUID,p_event_digest BYTEA,p_transport_provider_id TEXT,p_transport_profile_id UUID,p_cursor_handle BYTEA) RETURNS TABLE(outcome TEXT,receipt_id UUID,committed_at TIMESTAMPTZ,next_expected_sequence BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $function$ DECLARE active_tenant UUID := NULLIF(current_setting('app.tenant_id',true),'')::UUID; expected_seq BIGINT := 1; suspended TEXT := NULL; stored_row RECORD; BEGIN IF active_tenant IS NULL OR p_tenant_id IS DISTINCT FROM active_tenant THEN RAISE EXCEPTION 'Collaboration tenant scope mismatch' USING ERRCODE = '42501'; END IF; IF p_tenant_id IS NULL OR p_stream_id IS NULL OR p_source_sequence IS NULL OR p_source_sequence <= 0 OR p_event_id IS NULL OR p_actor_id IS NULL OR p_device_id IS NULL OR p_device_generation IS NULL OR p_device_generation <= 0 OR p_occurred_at IS NULL OR p_correlation_id IS NULL OR p_event_digest IS NULL OR octet_length(p_event_digest) <> 32 OR p_transport_provider_id !~ '^[a-z0-9][a-z0-9-]{0,63}$' OR p_transport_profile_id IS NULL OR (p_cursor_handle IS NOT NULL AND octet_length(p_cursor_handle) > 128) THEN RAISE EXCEPTION 'invalid identity device revoke event envelope' USING ERRCODE = '23514'; END IF; IF p_producer_id IS DISTINCT FROM 'identity.device-revoke.v1' THEN RAISE EXCEPTION 'identity device revoke producer scope mismatch' USING ERRCODE = '42501'; END IF; IF p_event_type IS DISTINCT FROM 'device.revoked' OR p_schema_version IS DISTINCT FROM 1 THEN INSERT INTO public.collaboration_device_event_incident (tenant_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) VALUES (p_tenant_id,p_producer_id,p_stream_id,p_source_sequence,p_event_id,'unknown_schema_version',p_event_digest) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) DO NOTHING; RETURN QUERY SELECT 'rejected'::TEXT,NULL::UUID,NULL::TIMESTAMPTZ,1::BIGINT; RETURN; END IF; SELECT next_expected_sequence,suspended_reason INTO expected_seq,suspended FROM public.collaboration_inbox_checkpoint WHERE tenant_id=p_tenant_id AND consumer_id='collab.device-auth.v1' AND producer_id=p_producer_id AND stream_id=p_stream_id AND transport_profile_id=p_transport_profile_id FOR UPDATE; IF NOT FOUND THEN expected_seq := 1; suspended := NULL; END IF; IF suspended IS NOT NULL THEN RETURN QUERY SELECT 'suspended'::TEXT,NULL::UUID,NULL::TIMESTAMPTZ,expected_seq; RETURN; END IF; IF p_source_sequence > expected_seq THEN INSERT INTO public.collaboration_device_event_incident (tenant_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) VALUES (p_tenant_id,p_producer_id,p_stream_id,p_source_sequence,p_event_id,'sequence_gap',p_event_digest) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) DO NOTHING; INSERT INTO public.collaboration_inbox_checkpoint (tenant_id,consumer_id,producer_id,stream_id,transport_provider_id,transport_profile_id,cursor_handle,next_expected_sequence,suspended_reason,suspended_at,updated_at) VALUES (p_tenant_id,'collab.device-auth.v1',p_producer_id,p_stream_id,p_transport_provider_id,p_transport_profile_id,COALESCE(p_cursor_handle,''),expected_seq,'sequence_gap',clock_timestamp(),clock_timestamp()) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,transport_profile_id) DO UPDATE SET suspended_reason=EXCLUDED.suspended_reason,suspended_at=EXCLUDED.suspended_at,cursor_handle=COALESCE(p_cursor_handle,public.collaboration_inbox_checkpoint.cursor_handle),updated_at=clock_timestamp(); RETURN QUERY SELECT 'sequence_gap'::TEXT,NULL::UUID,NULL::TIMESTAMPTZ,expected_seq; RETURN; END IF; INSERT INTO public.collaboration_device_inbox (tenant_id,consumer_id,producer_id,stream_id,source_sequence,event_id,event_type,schema_version,actor_id,device_id,device_generation,occurred_at,correlation_id,event_digest,transport_provider_id,transport_profile_id) VALUES (p_tenant_id,'collab.device-auth.v1',p_producer_id,p_stream_id,p_source_sequence,p_event_id,p_event_type,p_schema_version,p_actor_id,p_device_id,p_device_generation,p_occurred_at,p_correlation_id,p_event_digest,p_transport_provider_id,p_transport_profile_id) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,source_sequence,event_id) DO NOTHING RETURNING public.collaboration_device_inbox.receipt_id,public.collaboration_device_inbox.committed_at INTO stored_row.receipt_id,stored_row.committed_at; IF FOUND THEN INSERT INTO public.collaboration_device_projection (tenant_id,consumer_id,actor_id,device_id,device_generation,status,source_event_id,invalidated_at) VALUES (p_tenant_id,'collab.device-auth.v1',p_actor_id,p_device_id,p_device_generation,'revoked',p_event_id,p_occurred_at) ON CONFLICT (tenant_id,consumer_id,actor_id,device_id) DO UPDATE SET device_generation=EXCLUDED.device_generation,status=EXCLUDED.status,source_event_id=EXCLUDED.source_event_id,invalidated_at=EXCLUDED.invalidated_at WHERE public.collaboration_device_projection.device_generation < EXCLUDED.device_generation; INSERT INTO public.collaboration_inbox_checkpoint (tenant_id,consumer_id,producer_id,stream_id,transport_provider_id,transport_profile_id,cursor_handle,next_expected_sequence,updated_at) VALUES (p_tenant_id,'collab.device-auth.v1',p_producer_id,p_stream_id,p_transport_provider_id,p_transport_profile_id,COALESCE(p_cursor_handle,''),p_source_sequence+1,clock_timestamp()) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,transport_profile_id) DO UPDATE SET next_expected_sequence=EXCLUDED.next_expected_sequence,cursor_handle=COALESCE(p_cursor_handle,public.collaboration_inbox_checkpoint.cursor_handle),suspended_reason=NULL,suspended_at=NULL,updated_at=clock_timestamp() WHERE public.collaboration_inbox_checkpoint.next_expected_sequence <= p_source_sequence; RETURN QUERY SELECT 'committed'::TEXT,stored_row.receipt_id,stored_row.committed_at,p_source_sequence+1; RETURN; END IF; SELECT i.* INTO stored_row FROM public.collaboration_device_inbox AS i WHERE i.tenant_id=p_tenant_id AND i.consumer_id='collab.device-auth.v1' AND i.producer_id=p_producer_id AND i.stream_id=p_stream_id AND i.source_sequence=p_source_sequence AND i.event_id=p_event_id; IF FOUND AND stored_row.event_type IS NOT DISTINCT FROM p_event_type AND stored_row.schema_version IS NOT DISTINCT FROM p_schema_version AND stored_row.actor_id IS NOT DISTINCT FROM p_actor_id AND stored_row.device_id IS NOT DISTINCT FROM p_device_id AND stored_row.device_generation IS NOT DISTINCT FROM p_device_generation AND stored_row.occurred_at IS NOT DISTINCT FROM p_occurred_at AND stored_row.correlation_id IS NOT DISTINCT FROM p_correlation_id AND stored_row.event_digest IS NOT DISTINCT FROM p_event_digest AND stored_row.transport_provider_id IS NOT DISTINCT FROM p_transport_provider_id AND stored_row.transport_profile_id IS NOT DISTINCT FROM p_transport_profile_id THEN RETURN QUERY SELECT 'exact_replay'::TEXT,stored_row.receipt_id,stored_row.committed_at,GREATEST(expected_seq,p_source_sequence+1); RETURN; END IF; IF FOUND THEN INSERT INTO public.collaboration_device_event_incident (tenant_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest,stored_event_digest) VALUES (p_tenant_id,p_producer_id,p_stream_id,p_source_sequence,p_event_id,'digest_conflict',p_event_digest,stored_row.event_digest) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) DO NOTHING; RETURN QUERY SELECT 'conflict'::TEXT,NULL::UUID,NULL::TIMESTAMPTZ,expected_seq; RETURN; END IF; INSERT INTO public.collaboration_device_event_incident (tenant_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) VALUES (p_tenant_id,p_producer_id,p_stream_id,p_source_sequence,p_event_id,'stale_cursor',p_event_digest) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,source_sequence,event_id,reason_code,received_event_digest) DO NOTHING; INSERT INTO public.collaboration_inbox_checkpoint (tenant_id,consumer_id,producer_id,stream_id,transport_provider_id,transport_profile_id,cursor_handle,next_expected_sequence,suspended_reason,suspended_at,updated_at) VALUES (p_tenant_id,'collab.device-auth.v1',p_producer_id,p_stream_id,p_transport_provider_id,p_transport_profile_id,COALESCE(p_cursor_handle,''),expected_seq,'stale_cursor',clock_timestamp(),clock_timestamp()) ON CONFLICT (tenant_id,consumer_id,producer_id,stream_id,transport_profile_id) DO UPDATE SET suspended_reason=EXCLUDED.suspended_reason,suspended_at=EXCLUDED.suspended_at,cursor_handle=COALESCE(p_cursor_handle,public.collaboration_inbox_checkpoint.cursor_handle),updated_at=clock_timestamp(); RETURN QUERY SELECT 'stale_cursor'::TEXT,NULL::UUID,NULL::TIMESTAMPTZ,expected_seq; RETURN; END; $function$;
CREATE OR REPLACE FUNCTION public.read_device_revocation_projection(p_tenant_id UUID,p_actor_id UUID,p_device_id UUID) RETURNS TABLE(device_generation BIGINT,status TEXT,source_event_id UUID,invalidated_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $function$ BEGIN IF p_tenant_id IS NULL OR p_tenant_id IS DISTINCT FROM NULLIF(current_setting('app.tenant_id',true),'')::UUID THEN RAISE EXCEPTION 'Collaboration tenant scope mismatch' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT p.device_generation,p.status,p.source_event_id,p.invalidated_at FROM public.collaboration_device_projection AS p WHERE p.tenant_id=p_tenant_id AND p.consumer_id='collab.device-auth.v1' AND p.actor_id=p_actor_id AND p.device_id=p_device_id ORDER BY p.device_generation DESC LIMIT 1; END; $function$;
CREATE OR REPLACE FUNCTION public.read_collaboration_inbox_checkpoint(p_tenant_id UUID,p_stream_id UUID,p_transport_provider_id TEXT,p_transport_profile_id UUID) RETURNS TABLE(cursor_handle BYTEA,next_expected_sequence BIGINT,suspended_reason TEXT,suspended_at TIMESTAMPTZ,updated_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $function$ BEGIN IF p_tenant_id IS NULL OR p_tenant_id IS DISTINCT FROM NULLIF(current_setting('app.tenant_id',true),'')::UUID THEN RAISE EXCEPTION 'Collaboration tenant scope mismatch' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT c.cursor_handle,c.next_expected_sequence,c.suspended_reason,c.suspended_at,c.updated_at FROM public.collaboration_inbox_checkpoint AS c WHERE c.tenant_id=p_tenant_id AND c.consumer_id='collab.device-auth.v1' AND c.producer_id='identity.device-revoke.v1' AND c.stream_id=p_stream_id AND c.transport_provider_id=p_transport_provider_id AND c.transport_profile_id=p_transport_profile_id LIMIT 1; END; $function$;
ALTER FUNCTION public.commit_device_revoke_event_v1(UUID,TEXT,UUID,BIGINT,UUID,TEXT,INTEGER,UUID,UUID,BIGINT,TIMESTAMPTZ,UUID,BYTEA,TEXT,UUID,BYTEA) OWNER TO star_collaboration_owner;
ALTER FUNCTION public.read_device_revocation_projection(UUID,UUID,UUID) OWNER TO star_collaboration_owner;
ALTER FUNCTION public.read_collaboration_inbox_checkpoint(UUID,UUID,TEXT,UUID) OWNER TO star_collaboration_owner;
REVOKE ALL ON FUNCTION public.commit_device_revoke_event_v1(UUID,TEXT,UUID,BIGINT,UUID,TEXT,INTEGER,UUID,UUID,BIGINT,TIMESTAMPTZ,UUID,BYTEA,TEXT,UUID,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.read_device_revocation_projection(UUID,UUID,UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.read_collaboration_inbox_checkpoint(UUID,UUID,TEXT,UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.commit_device_revoke_event_v1(UUID,TEXT,UUID,BIGINT,UUID,TEXT,INTEGER,UUID,UUID,BIGINT,TIMESTAMPTZ,UUID,BYTEA,TEXT,UUID,BYTEA) TO star_collaboration_runtime;
GRANT EXECUTE ON FUNCTION public.read_device_revocation_projection(UUID,UUID,UUID) TO star_collaboration_runtime;
GRANT EXECUTE ON FUNCTION public.read_collaboration_inbox_checkpoint(UUID,UUID,TEXT,UUID) TO star_collaboration_runtime;
COMMENT ON FUNCTION public.commit_device_revoke_event_v1(UUID,TEXT,UUID,BIGINT,UUID,TEXT,INTEGER,UUID,UUID,BIGINT,TIMESTAMPTZ,UUID,BYTEA,TEXT,UUID,BYTEA) IS 'Commits the Collaboration Inbox receipt, the local invalidation projection and the cursor advance atomically; exact replays return the stable receipt; digest conflicts, sequence gaps and stale cursors are recorded as incidents and fail closed without advancing the cursor.';
COMMENT ON FUNCTION public.read_device_revocation_projection(UUID,UUID,UUID) IS 'Owner-scoped projection lookup used only to accelerate shared-work authorization expiry; zero rows means no revocation fact, which is never a valid authorization on its own.';

